import React from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import {
  Modal,
  Button,
  Form,
  Input,
  Select,
  Icon,
  Upload,
  notification,
  message
} from 'antd'
import EndorsePolicyModalWrapper from './endorsePolicyModal.style'
import { get } from 'lodash/object'
import { size } from 'lodash/collection'
import validator from '../../../helpers/validator'
import policyActions from '../../../redux/policy/actions'
import masterDataActions from '../../redux/masterdata/actions'
import moment from 'moment'

const { uploadEndorsePolicyFile, resetReduxState: resetPolicyRedux, endorsePolicy, resetEndorsePolicyFile } = policyActions
const { getMasterData, resetReduxMasterData } = masterDataActions

const Option = Select.Option

class ModalClaimConfirmation extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      images: 4

    }
  }

  componentDidMount () {
    // this.props.resetPolicyRedux(['endorsePolicyFile', 'endorsePolicyFileLoading', 'uploadEndorsePolicyFileMessage'])
    this.props.resetReduxMasterData(['endorsePolicyMessage'])
    this.props.getMasterData({ params: { tag: 'gadget-brand' }, extra: { key: 'gadgetBrands' } })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      uploadEndorsePolicyFileMessage,
      uploadEndorsePolicyFileLoading,
      uploadEndorsePolicyFileError,
      getMasterDataLoading,
      getMasterDataError,
      getMasterDataMessage,
      endorsePolicyMessage,
      endorsePolicyLoading,
      endorsePolicyError
    } = nextProps
    if (!uploadEndorsePolicyFileLoading && !!uploadEndorsePolicyFileError && !!uploadEndorsePolicyFileMessage) {
      notification.error({
        title: 'Error',
        message: uploadEndorsePolicyFileMessage
      })
      this.props.resetPolicyRedux(['uploadEndorsePolicyFileMessage'])
    }
    if (!getMasterDataLoading && !!getMasterDataError && !!getMasterDataMessage) {
      notification.error({
        title: 'Error',
        message: getMasterDataMessage
      })
      this.props.resetReduxMasterData(['getMasterDataMessage'])
    }
    if (!endorsePolicyLoading && !!endorsePolicyMessage) {
      notification[endorsePolicyError ? 'error' : 'success']({
        title: endorsePolicyError ? 'Error' : 'Success',
        message: endorsePolicyMessage
      })
      this.props.resetPolicyRedux(['endorsePolicyMessage'])
      if (!endorsePolicyError) {
        this.handleOk()
        this.props.getPolicyDetails()
      }
    }
  }

  handleCancel = () => {
    this.props.rejecting()
  }

  handleOk = () => {
    this.props.confirming()
  }

  handleSubmit = (e) => {
    e.preventDefault()
    const { policyDetail, endorsePolicyFile } = this.props
    const { CreatedAt, InternalID: internalId } = policyDetail
    const createdAtDate = moment(CreatedAt)
    const currentDate = moment()
    const dayDifference = Math.abs(createdAtDate.diff(currentDate, 'days')) + 1
    const dayDifferenceLimit = 7
    const self = this

    this.props.form.setFieldsValue(endorsePolicyFile) // set uploaded file urls from props to fields
    this.props.form.validateFields((err, values) => {
      if (!err) {
        if (dayDifference > dayDifferenceLimit) {
          Modal.confirm({
            title: 'Warning',
            content: 'This policy was created more than 7 days ago. Are you sure you want to activate the policy?',
            onOk () {
              self.props.endorsePolicy({ body: { ...values, force: true }, params: { internalId } })
              // await self.props.confirming()
              // await window.location.reload()
            },
            onCancel () {
              // await self.props.rejecting()
              // window.location.reload()
            }
          })
        } else {
          this.props.endorsePolicy({ body: values, params: { internalId } })
          // this.props.confirming()
        }
      }
    })
  }

  customRequest = (file, key) => {
    const body = new FormData()
    body.append('file', file)
    this.props.uploadEndorsePolicyFile({ body, extra: { key } })
  }

  customRequestPhoto = (file, key) => {
    const supportedImageTypes = ['image/jpeg', 'image/jpg', 'image/png']
    const isLt10KB = file.size / 1024 / 1024 < 0.01
    const isGt5000KB = file.size / 1024 / 1024 > 5
    const isImage = supportedImageTypes.includes(file.type)
    const isValidImage = isImage && !isLt10KB && !isGt5000KB

    if (isImage) {
      if (!isValidImage) {
        if (isLt10KB) {
          message.error('Photo terlalu kecil, min 10kb')
          return
        }
        if (isGt5000KB) {
          message.error('Photo terlalu besar, max 5mb')
        }
      } else {
        this.customRequest(file, key)
      }
    } else {
      message.error(`File bukan ${supportedImageTypes.join(', ')}`)
    }
  }

  customRequestVideo = (file, key) => {
    const supportedVideoTypes = ['video/mp4']
    const isLt10KB = file.size / 1024 / 1024 < 0.01
    const isGt10Mb = file.size / 1024 / 1024 > 10
    const isVideo = supportedVideoTypes.includes(file.type)
    const isValidVideo = isVideo && !isLt10KB && !isGt10Mb

    if (isVideo) {
      if (!isValidVideo) {
        if (isLt10KB) {
          message.error('Video terlalu kecil, min 10kb')
          return
        }
        if (isGt10Mb) {
          message.error('Video terlalu besar, max 10mb')
        }
      } else {
        this.customRequest(file, key)
      }
    } else {
      message.error(`File bukan ${supportedVideoTypes.join(', ')}`)
    }
  }

  toggleImageModal = (url = '') => {
    this.setState((prevState) => ({
      imagePreviewUrl: url,
      isImagePreviewModalOpen: !prevState.isImagePreviewModalOpen
    }))
  }

  toggleVideoModal = (url = '') => {
    this.setState((prevState) => ({
      videoPreviewUrl: url,
      isVideoPreviewModalOpen: !prevState.isVideoPreviewModalOpen
    }))
  }

  resetField = (key) => {
    this.props.form.resetFields([key])
    this.props.resetEndorsePolicyFile({ [key]: '' })
  }

  renderImageFormItems () {
    const {
      images
    } = this.state
    const {
      policyDetail,
      endorsePolicyFile,
      endorsePolicyFileLoading
    } = this.props
    const { getFieldDecorator } = this.props.form
    const formItems = []
    for (let i = 1; i <= images; i++) {
      const imageUrl = get(endorsePolicyFile, `image_${i}`)
      const productSerach = (size(policyDetail) > 0 && get(policyDetail, 'ProductKey', '')) === 'simple-crack-screen-protection-pro'
      const isFirstImage = i === 1
      const formItem = (
        <Form.Item
          label={`Image ${i}`}
        >
          {getFieldDecorator(`image_${i}`, {
            rules: [{ required: productSerach || isFirstImage, message: 'Please upload image!' }]
          })(
            <Upload
              showUploadList={false}
              multiple={false}
              customRequest={({ file }) => this.customRequestPhoto(file, `image_${i}`)}
            >
              <Button
                style={{
                  marginBottom: '10px'
                }}
                className='upload-btn'
                disabled={get(endorsePolicyFileLoading, `image_${i}`)}
                loading={get(endorsePolicyFileLoading, `image_${i}`)}
              >
                <Icon type='upload' /> Upload
              </Button>
            </Upload>
          )}
          <br />
          {!!imageUrl && (
            <div>
              <img
                className='image-preview'
                src={imageUrl}
                alt=''
                onClick={() => this.toggleImageModal(imageUrl)}
              />
              <Icon
                type='close'
                onClick={() => this.resetField(`image_${i}`)}
                style={{
                  color: 'red',
                  paddingLeft: 10
                }}
              />
            </div>
          )}
        </Form.Item>
      )
      formItems.push(formItem)
    }
    return formItems
  }

  render () {
    const {
      isImagePreviewModalOpen,
      imagePreviewUrl,
      isVideoPreviewModalOpen,
      videoPreviewUrl
    } = this.state
    const {
      isOpen,
      endorsePolicyFile,
      endorsePolicyFileLoading,
      gadgetBrands,
      getMasterDataLoading
    } = this.props
    const { getFieldDecorator } = this.props.form
    const formItemLayout = {
      labelAlign: 'left',
      labelCol: {
        xs: { span: 24 },
        sm: { span: 4 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 20 }
      }
    }
    return (
      <Modal
        title='Endorse Policy'
        visible={isOpen}
        footer={null}
        closable
        // wrapClassName='benefits-modal'
        maskClosable={false}
        centered
        onCancel={this.handleCancel}
      >
        <EndorsePolicyModalWrapper>
          <Modal
            closable
            visible={isImagePreviewModalOpen}
            onOk={() => this.toggleImageModal()}
            onCancel={() => this.toggleImageModal()}
            style={{
              minWidth: '100%'
            }}
          >
            <img style={{ maxWidth: '100%' }} src={imagePreviewUrl} alt='' />
          </Modal>
          <Modal
            closable
            visible={isVideoPreviewModalOpen}
            onOk={() => this.toggleVideoModal()}
            onCancel={() => this.toggleVideoModal()}
            style={{
              minWidth: '100%',
              textAlign: 'center'
            }}
          >
            <video style={{ maxWidth: '100%' }} className='video-preview' controls>
              <source src={videoPreviewUrl} type='video/mp4' />
              Your browser does not support the video tag.
            </video>
          </Modal>
          <Form
            {...formItemLayout}
            onSubmit={(e) => { this.handleSubmit(e) }}
            className='endorse-modal'
          >
            <Form.Item
              label='Brand'
            >
              {getFieldDecorator('brand', {
                rules: [{ required: true, message: 'Please choose phone brand!' }]
              })(
                <Select
                  className='brand-select'
                  showSearch
                  placeholder='Brand'
                  optionFilterProp='children'
                  filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                  disabled={!!getMasterDataLoading}
                  loading={!!getMasterDataLoading}
                >
                  {gadgetBrands.map(({ display_name: displayName }) => (
                    <Option value={displayName} key={displayName}>{displayName}</Option>
                  ))}
                </Select>
              )}
            </Form.Item>
            <Form.Item
              label='Model'
            >
              {getFieldDecorator('model', {
                rules: [{ required: true, message: 'Please input phone model!' }]
              })(
                <Input placeholder='Model' />
              )}
            </Form.Item>
            <Form.Item
              label='IMEI 1'
            >
              {getFieldDecorator('imei_1', {
                rules: [
                  { required: true, message: 'Please input phone IMEI!' },
                  { validator: validator.checkIMEInumber }
                ]
              })(
                <Input placeholder='IMEI' />
              )}
            </Form.Item>
            <Form.Item
              label='IMEI 2'
            >
              {getFieldDecorator('imei_2', {
                rules: [
                  { required: false, message: 'Please input phone IMEI!' }
                ]
              })(
                <Input placeholder='IMEI' />
              )}
            </Form.Item>
            {this.renderImageFormItems()}
            <Form.Item
              label='Video 1'
            >
              {getFieldDecorator('video_1', {
                rules: [{ required: true, message: 'Please input video!' }]
              })(
                <Upload
                  showUploadList={false}
                  multiple={false}
                  customRequest={({ file }) => this.customRequestVideo(file, 'video_1')}
                >
                  <Button
                    style={{
                      marginBottom: '10px'
                    }}
                    className='upload-btn'
                    disabled={get(endorsePolicyFileLoading, 'video_1')}
                    loading={get(endorsePolicyFileLoading, 'video_1')}
                  >
                    <Icon type='upload' /> Upload
                  </Button>
                </Upload>
              )}
              <br />
              {!!get(endorsePolicyFile, 'video_1') && (
                <div>
                  <span
                    className='anchor'
                    onClick={() => this.toggleVideoModal(get(endorsePolicyFile, 'video_1'))}
                  >
                    Preview Video
                  </span>
                  <Icon
                    type='close'
                    onClick={() => this.resetField('video_1')}
                    style={{
                      color: 'red',
                      paddingLeft: 10
                    }}
                  />
                </div>
              )}
            </Form.Item>
            <Form.Item>
              <Button type='primary' htmlType='submit' className='login-form-button'>
                Submit
              </Button>
            </Form.Item>
          </Form>
        </EndorsePolicyModalWrapper>
      </Modal>
    )
  }
}

ModalClaimConfirmation.propTypes = {
  gadgetBrands: PropTypes.array.isRequired,
  policyDetail: PropTypes.object.isRequired
}

ModalClaimConfirmation.defaultProps = {
  gadgetBrands: [],
  policyDetail: {}
}

const WrappedModalClaimConfirmation = Form.create()(ModalClaimConfirmation)

export default connect(
  state => ({
    endorsePolicyFile: state.Policy.endorsePolicyFile,
    endorsePolicyFileLoading: state.Policy.endorsePolicyFileLoading,
    getMasterDataLoading: state.Loading.GET_MASTER_DATA,
    getMasterDataError: state.Error.GET_MASTER_DATA,
    uploadEndorsePolicyFileLoading: state.Loading.UPLOAD_ENDORSE_POLICY_FILE,
    uploadEndorsePolicyFileError: state.Error.UPLOAD_ENDORSE_POLICY_FILE,
    uploadEndorsePolicyFileMessage: state.Policy.uploadEndorsePolicyFileMessage,
    gadgetBrands: state.MasterData.gadgetBrands,
    getMasterDataMessage: state.MasterData.getMasterDataMessage,
    endorsePolicyLoading: state.Loading.ENDORSE_POLICY,
    endorsePolicyError: state.Error.ENDORSE_POLICY,
    endorsePolicyMessage: state.Policy.endorsePolicyMessage
  }),
  {
    uploadEndorsePolicyFile,
    resetPolicyRedux,
    getMasterData,
    resetReduxMasterData,
    endorsePolicy,
    resetEndorsePolicyFile
  }
)(WrappedModalClaimConfirmation)
