import React, { Component } from 'react'
import { Modal, Form, Input, Upload, Button, Icon, message, notification } from 'antd'
import EndorsePolicyModalWrapper from './endorsePolicyModal.style'
import validation from '../../../helpers/validator'
import { connect } from 'react-redux'
import { get } from 'lodash/object'
import { size } from 'lodash/collection'
import policyActions from '../../../redux/policy/actions'
import moment from 'moment'

const { uploadEndorsePolicyFile, resetReduxState: resetPolicyRedux, endorsePolicy } = policyActions

class endorsementVehicleModal extends Component {
  constructor (props) {
    super(props)
    this.state = {
      images: 4
    }
  }

  handleSubmit = (e) => {
    e.preventDefault()
    const { policyDetail, endorsePolicyFile } = this.props
    const { CreatedAt, InternalID: internalId } = policyDetail
    const createdAtDate = moment(CreatedAt)
    const currentDate = moment()
    const dayDifference = Math.abs(createdAtDate.diff(currentDate, 'days')) + 1
    const dayDifferenceLimit = 7
    this.props.form.setFieldsValue(endorsePolicyFile)
    this.props.form.validateFields((err, values) => {
      if (!err) {
        if (dayDifference > dayDifferenceLimit) {
          Modal.confirm({
            title: 'Warning',
            content: 'This policy was created more than 7 days ago. Are you sure you want to activate the policy?',
            onOk () {
              this.props.endorsePolicy({ body: { ...values, force: true }, params: { internalId } })
              // await self.props.confirming()
              // await window.location.reload()
            },
            onCancel () {
              // await self.props.rejecting()
              // window.location.reload()
            }
          })
        } else {
          this.props.endorsePolicy({ body: values, params: { internalId } })
          // this.props.confirming()
        }
      }
    })
  }

  customRequest = (file, key) => {
    const body = new FormData()
    body.append('file', file)
    this.props.uploadEndorsePolicyFile({ body, extra: { key } })
  }

  customRequestPhoto = (file, key) => {
    const supportedImageTypes = ['image/jpeg', 'image/jpg', 'image/png']
    const isLt10KB = file.size / 1024 / 1024 < 0.01
    const isGt5000KB = file.size / 1024 / 1024 > 5
    const isImage = supportedImageTypes.includes(file.type)
    const isValidImage = isImage && !isLt10KB && !isGt5000KB

    if (isImage) {
      if (!isValidImage) {
        if (isLt10KB) {
          message.error('Photo terlalu kecil, min 10kb')
          return
        }
        if (isGt5000KB) {
          message.error('Photo terlalu besar, max 5mb')
        }
      } else {
        this.customRequest(file, key)
      }
    } else {
      message.error(`File bukan ${supportedImageTypes.join(', ')}`)
    }
  }

  getImageLabel = (index) => {
    switch (index) {
      case 1:
        return 'front'
      case 2:
        return 'back'
      case 3:
        return 'left'
      case 4:
        return 'right'
      default:
        return { index }
    }
  }

  renderImageFormItems () {
    const {
      images
    } = this.state
    const {
      policyDetail,
      endorsePolicyFile,
      endorsePolicyFileLoading
    } = this.props
    const { getFieldDecorator } = this.props.form
    const formItems = []
    for (let i = 1; i <= images; i++) {
      const imageUrl = get(endorsePolicyFile, `${this.getImageLabel(i)}_photo`)
      const productSerach = (size(policyDetail) > 0 && get(policyDetail, 'ProductKey', '')) === 'vehicle-protection'
      const isFirstImage = i === 1
      const formItem = (
        <Form.Item
          className='imageUploadLabel'
          label={`${this.getImageLabel(i)} Side`}
        >
          {getFieldDecorator(`${this.getImageLabel(i)}_photo`, {
            rules: [{ required: productSerach || isFirstImage, message: 'Please upload image!' }]
          })(
            <Upload
              showUploadList={false}
              multiple={false}
              customRequest={({ file }) => this.customRequestPhoto(file, `${this.getImageLabel(i)}_photo`)}
            >
              <Button
                style={{
                  marginBottom: '10px'
                }}
                className='upload-btn'
                disabled={get(endorsePolicyFileLoading, `${this.getImageLabel(i)}_photo`)}
                loading={get(endorsePolicyFileLoading, `${this.getImageLabel(i)}_photo`)}
              >
                <Icon type='upload' /> Upload
              </Button>
            </Upload>
          )}
          <br />
          {!!imageUrl && (
            <div>
              <img
                className='image-preview'
                src={imageUrl}
                onClick={() => this.toggleImageModal(imageUrl)}
                alt=''
              />
              <Icon
                type='close'
                onClick={() => this.resetField(`image_${i}`)}
                style={{
                  color: 'red',
                  paddingLeft: 10
                }}
              />
            </div>
          )}
        </Form.Item>
      )
      formItems.push(formItem)
    }
    return formItems
  }

  toggleImageModal = (url = '') => {
    this.setState((prevState) => ({
      imagePreviewUrl: url,
      isImagePreviewModalOpen: !prevState.isImagePreviewModalOpen
    }))
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      uploadEndorsePolicyFileMessage,
      uploadEndorsePolicyFileLoading,
      uploadEndorsePolicyFileError,
      getMasterDataLoading,
      getMasterDataError,
      getMasterDataMessage,
      endorsePolicyMessage,
      endorsePolicyLoading,
      endorsePolicyError
    } = nextProps
    if (!uploadEndorsePolicyFileLoading && !!uploadEndorsePolicyFileError && !!uploadEndorsePolicyFileMessage) {
      notification.error({
        title: 'Error',
        message: uploadEndorsePolicyFileMessage
      })
      this.props.resetPolicyRedux(['uploadEndorsePolicyFileMessage'])
    }
    if (!getMasterDataLoading && !!getMasterDataError && !!getMasterDataMessage) {
      notification.error({
        title: 'Error',
        message: getMasterDataMessage
      })
      this.props.resetReduxMasterData(['getMasterDataMessage'])
    }
    if (!endorsePolicyLoading && !!endorsePolicyMessage) {
      notification[endorsePolicyError ? 'error' : 'success']({
        title: endorsePolicyError ? 'Error' : 'Success',
        message: endorsePolicyMessage
      })
      this.props.resetPolicyRedux(['endorsePolicyMessage'])
      if (!endorsePolicyError) {
        this.handleOk()
        this.props.getPolicyDetails()
      }
    }
  }

  handleCancel = () => {
    this.props.rejecting()
  }

  handleOk = () => {
    this.props.confirming()
  }

  render () {
    const {
      isImagePreviewModalOpen,
      imagePreviewUrl
    } = this.state
    const { isOpen } = this.props
    const { getFieldDecorator } = this.props.form
    const formItemLayout = {
      labelAlign: 'left',
      labelCol: {
        xs: { span: 24 },
        sm: { span: 6 }
      },
      wrapperCol: {
        xs: { span: 24 },
        sm: { span: 18 }
      }
    }
    return (
      <Modal
        title='Endorse Policy'
        visible={isOpen}
        footer={null}
        closable
        // wrapClassName='benefits-modal'
        maskClosable={false}
        centered
        onCancel={this.handleCancel}
        width='100vh'
      >
        <Modal
          closable
          visible={isImagePreviewModalOpen}
          onOk={() => this.toggleImageModal()}
          onCancel={() => this.toggleImageModal()}
        >
          <img alt='' style={{ maxWidth: '100%', marginTop: '25px' }} src={imagePreviewUrl} />
        </Modal>
        <EndorsePolicyModalWrapper>
          <Form
            {...formItemLayout}
            onSubmit={(e) => { this.handleSubmit(e) }}
            className='endorse-modal'
          >
            <Form.Item label='KTP'>
              {getFieldDecorator('ktp', {
                rules: [{ required: true, message: 'Please input KTP!' }, { validator: validation.validateIdentityKtp }]
              })(
                <Input placeholder='KTP' />
              )}
            </Form.Item>
            <Form.Item label='Vehicle Color'>
              {getFieldDecorator('vehicle_color', {
                rules: [{ required: true, message: 'Please input Vehicle Color!' }, { validator: validation.validateColor }]
              })(
                <Input placeholder='Vehicle Color' />
              )}
            </Form.Item>
            <Form.Item label='Chassis Number'>
              {getFieldDecorator('chassis_number', {
                rules: [{ required: true, message: 'Please input Chassis Number!' }, { validator: validation.validateChasisNumber }]
              })(
                <Input placeholder='Chassis Number' />
              )}
            </Form.Item>
            <Form.Item label='Vehicle Plate no'>
              {getFieldDecorator('vehicle_plate', {
                rules: [{ required: true, message: 'Please input Vehicle Plate no!' }, { validator: validation.checkPlateNumber }]
              })(
                <Input placeholder='Vehicle Plate no ' />
              )}
            </Form.Item>
            <Form.Item label='Engine Number'>
              {getFieldDecorator('engine_number', {
                rules: [{ required: true, message: 'Please input Engine Number!' }, { validator: validation.validateEngineNumber }]
              })(
                <Input placeholder='Engine Number' />
              )}
            </Form.Item>
            {this.renderImageFormItems()}
            <Form.Item>
              <Button type='primary' htmlType='submit' className='login-form-button'>
                Submit
              </Button>
            </Form.Item>
          </Form>
        </EndorsePolicyModalWrapper>
      </Modal>
    )
  }
}

const EndorsementVehicleModalForm = Form.create()(endorsementVehicleModal)
export default connect(state => ({
  endorsePolicyFile: state.Policy.endorsePolicyFile,
  endorsePolicyFileLoading: state.Policy.endorsePolicyFileLoading,
  getMasterDataLoading: state.Loading.GET_MASTER_DATA,
  getMasterDataError: state.Error.GET_MASTER_DATA,
  uploadEndorsePolicyFileLoading: state.Loading.UPLOAD_ENDORSE_POLICY_FILE,
  uploadEndorsePolicyFileError: state.Error.UPLOAD_ENDORSE_POLICY_FILE,
  uploadEndorsePolicyFileMessage: state.Policy.uploadEndorsePolicyFileMessage,
  gadgetBrands: state.MasterData.gadgetBrands,
  getMasterDataMessage: state.MasterData.getMasterDataMessage,
  endorsePolicyLoading: state.Loading.ENDORSE_POLICY,
  endorsePolicyError: state.Error.ENDORSE_POLICY,
  endorsePolicyMessage: state.Policy.endorsePolicyMessage
}), {
  uploadEndorsePolicyFile,
  endorsePolicy,
  resetPolicyRedux
})(EndorsementVehicleModalForm)
