import React from 'react'
import { Table } from 'antd'
import moment from 'moment'

const ChangeHistoryTable = ({ tableData }) => {
  const changeHistoryData = tableData
  const columnsChangeHistory = [
    {
      title: 'Field',
      dataIndex: 'field',
      key: 'field'
    }, {
      title: 'Change From',
      dataIndex: 'change_from',
      key: 'change_from'
    }, {
      title: 'Change To',
      dataIndex: 'change_to',
      key: 'change_to'
    }, {
      title: 'Changed by',
      dataIndex: 'changed_by',
      key: 'changed_by'
    }, {
      title: 'Updated On',
      dataIndex: 'updated_on',
      key: 'updated_on'
    }, {
      title: 'Version',
      dataIndex: 'version',
      key: 'version'
    }, {
      title: 'Reason for changing',
      dataIndex: 'remarks',
      key: 'remarks'
    }
  ]
  const dataChangeHistory = changeHistoryData.map((val, index) => {
    return {
      key: index,
      field: val.field,
      change_from: val.old_value,
      change_to: val.new_value,
      changed_by: val.updated_by,
      updated_on: moment.utc(val.created_at).format('YYYY-MM-DD HH:mm:ss'),
      version: val.version,
      remarks: val.remarks
    }
  })
  return (
    <Table
      pagination={{ pageSize: 25 }}
      columns={columnsChangeHistory}
      dataSource={dataChangeHistory}
      scroll={{ x: true }}
    />
  )
}

export default ChangeHistoryTable
